import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static class ModNumber {
        int value;

        ModNumber(long v) {
            v %= MOD;
            if (v < 0) v += MOD;
            value = (int) v;
        }

        static int modInverse(int a, int m) {
            int g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                int tmp = g % r;
                g = r;
                r = tmp;
                int x1 = y;
                int y1 = x - q * y;
                x = x1;
                y = y1;
            }
            return x < 0 ? x + m : x;
        }

        ModNumber add(ModNumber other) {
            int res = value + other.value;
            if (res >= MOD) res -= MOD;
            return new ModNumber(res);
        }

        ModNumber subtract(ModNumber other) {
            int res = value - other.value;
            if (res < 0) res += MOD;
            return new ModNumber(res);
        }

        static long fast_mod(long x, int m) {
            return x % m;
        }

        ModNumber multiply(ModNumber other) {
            long res = fast_mod((long) value * other.value, MOD);
            return new ModNumber(res);
        }

        ModNumber divide(ModNumber other) {
            return this.multiply(new ModNumber(modInverse(other.value, MOD)));
        }

        ModNumber inv() {
            return new ModNumber(modInverse(value, MOD));
        }

        ModNumber pow(long p) {
            assert p >= 0;
            ModNumber base = this;
            ModNumber result = new ModNumber(1);
            while (p > 0) {
                if ((p & 1) != 0) {
                    result = result.multiply(base);
                }
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof ModNumber)) return false;
            ModNumber other = (ModNumber) obj;
            return this.value == other.value;
        }

        @Override
        public int hashCode() {
            return Integer.hashCode(value);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        ModNumber[][] prob = new ModNumber[N][N];

        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(parts[j]);
                prob[i][j] = new ModNumber(p).divide(new ModNumber(100));
            }
        }

        Map<List<Boolean>, ModNumber> states = new HashMap<>();
        List<Boolean> init_mask = new ArrayList<>(Collections.nCopies(1 << N, false));
        init_mask.set(0, true);
        states.put(init_mask, new ModNumber(1));

        for (int left_idx = 0; left_idx < N; left_idx++) {
            Map<List<Boolean>, ModNumber> new_states_map = new HashMap<>();
            for (int mask_curr = 0; mask_curr < (1 << N); mask_curr++) {
                ModNumber product = new ModNumber(1);
                for (int right_idx = 0; right_idx < N; right_idx++) {
                    boolean bit = ((mask_curr >> right_idx) & 1) != 0;
                    if (bit) {
                        product = product.multiply(prob[left_idx][right_idx]);
                    } else {
                        product = product.multiply(new ModNumber(1).subtract(prob[left_idx][right_idx]));
                    }
                }
                for (Map.Entry<List<Boolean>, ModNumber> entry : states.entrySet()) {
                    List<Boolean> possible_mask = entry.getKey();
                    ModNumber prob_value = entry.getValue();
                    List<Boolean> temp_mask = new ArrayList<>(Collections.nCopies(1 << N, false));
                    for (int m = 0; m < (1 << N); m++) {
                        if (possible_mask.get(m)) {
                            for (int i = 0; i < N; i++) {
                                boolean maskBit = ((mask_curr >> i) & 1) != 0;
                                boolean mBit = ((m >> i) & 1) != 0;
                                if (maskBit && !mBit) {
                                    temp_mask.set(m | (1 << i), true);
                                }
                            }
                        }
                    }
                    // Add to new_states_map
                    new_states_map.put(temp_mask, new_states_map.getOrDefault(temp_mask, new ModNumber(0)).add(prob_value.multiply(product)));
                }
            }
            states = new_states_map;
        }

        ModNumber total = new ModNumber(0);
        int full_mask_index = (1 << N) - 1;
        for (Map.Entry<List<Boolean>, ModNumber> p : states.entrySet()) {
            List<Boolean> mask = p.getKey();
            if (mask.get(full_mask_index)) {
                total = total.add(p.getValue());
            }
        }

        System.out.println(total.value);
    }
}
